1	import { Router } from 'express'
2	import { runSavedSearch } from '../services/search-runner'
3	import {
4	  createSearch,
5	  deleteSearch,
6	  getAllSearches,
7	  updateSearch,
8	} from '../store/searches'
9	
10	const router = Router()
11	
12	router.get('/', async (_req, res) => {
13	  try {
14	    const searches = await getAllSearches()
15	    res.json(searches)
16	  } catch {
17	    res.status(500).json({ error: 'Failed to load searches' })
18	  }
19	})
20	
21	router.post('/', async (req, res) => {
22	  const { name, query, maxPrice, location, radius, resultsPerSearch } = req.body
23	
24	  if (!name || typeof name !== 'string' || !name.trim()) {
25	    res.status(400).json({ error: 'Name is required' })
26	    return
27	  }
28	
29	  if (!query || typeof query !== 'string' || !query.trim()) {
30	    res.status(400).json({ error: 'Query is required' })
31	    return
32	  }
33	
34	  if (!location || typeof location !== 'string' || !location.trim()) {
35	    res.status(400).json({ error: 'Location is required' })
36	    return
37	  }
38	
39	  if (radius === undefined || typeof radius !== 'number' || radius <= 0) {
40	    res.status(400).json({ error: 'Radius must be a positive number' })
41	    return
42	  }
43	
44	  if (
45	    maxPrice !== undefined &&
46	    maxPrice !== null &&
47	    (typeof maxPrice !== 'number' || maxPrice <= 0)
48	  ) {
49	    res.status(400).json({ error: 'Max price must be a positive number' })
50	    return
51	  }
52	
53	  if (
54	    resultsPerSearch !== undefined &&
55	    (typeof resultsPerSearch !== 'number' ||
56	      ![5, 10, 20, 50].includes(resultsPerSearch))
57	  ) {
58	    res.status(400).json({ error: 'Results per search must be 5, 10, 20, or 50' })
59	    return
60	  }
61	
62	  try {
63	    const search = await createSearch({
64	      name: name.trim(),
65	      query: query.trim(),
66	      maxPrice: maxPrice ?? null,
67	      location: location.trim(),
68	      radius,
69	      resultsPerSearch: resultsPerSearch ?? 10,
70	    })
71	    res.status(201).json(search)
72	  } catch {
73	    res.status(500).json({ error: 'Failed to create search' })
74	  }
75	})
76	
77	router.patch('/:id', async (req, res) => {
78	  const { name, query, maxPrice, location, radius, resultsPerSearch } = req.body
79	
80	  if (name !== undefined && (typeof name !== 'string' || !name.trim())) {
81	    res.status(400).json({ error: 'Name is required' })
82	    return
83	  }
84	
85	  if (query !== undefined && (typeof query !== 'string' || !query.trim())) {
86	    res.status(400).json({ error: 'Query is required' })
87	    return
88	  }
89	
90	  if (location !== undefined && (typeof location !== 'string' || !location.trim())) {
91	    res.status(400).json({ error: 'Location is required' })
92	    return
93	  }
94	
95	  if (radius !== undefined && (typeof radius !== 'number' || radius <= 0)) {
96	    res.status(400).json({ error: 'Radius must be a positive number' })
97	    return
98	  }
99	
100	  if (
101	    maxPrice !== undefined &&
102	    maxPrice !== null &&
103	    (typeof maxPrice !== 'number' || maxPrice <= 0)
104	  ) {
105	    res.status(400).json({ error: 'Max price must be a positive number' })
106	    return
107	  }
108	
109	  if (
110	    resultsPerSearch !== undefined &&
111	    (typeof resultsPerSearch !== 'number' ||
112	      ![5, 10, 20, 50].includes(resultsPerSearch))
113	  ) {
114	    res.status(400).json({ error: 'Results per search must be 5, 10, 20, or 50' })
115	    return
116	  }
117	
118	  try {
119	    const search = await updateSearch(req.params.id, {
120	      ...(name !== undefined && { name: name.trim() }),
121	      ...(query !== undefined && { query: query.trim() }),
122	      ...(location !== undefined && { location: location.trim() }),
123	      ...(radius !== undefined && { radius }),
124	      ...(maxPrice !== undefined && { maxPrice }),
125	      ...(resultsPerSearch !== undefined && { resultsPerSearch }),
126	    })
127	
128	    if (!search) {
129	      res.status(404).json({ error: 'Search not found' })
130	      return
131	    }
132	
133	    res.json(search)
134	  } catch {
135	    res.status(500).json({ error: 'Failed to update search' })
136	  }
137	})
138	
139	router.post('/:id/run', async (req, res) => {
140	  try {
141	    const result = await runSavedSearch(req.params.id)
142	
143	    if (!result) {
144	      res.status(404).json({ error: 'Search not found' })
145	      return
146	    }
147	
148	    res.json(result)
149	  } catch (error) {
150	    console.error('Failed to run search:', error)
151	
152	    if (error instanceof Error && error.cause) {
153	      console.error('Caused by:', error.cause)
154	    }
155	
156	    res.status(500).json({ error: 'Failed to run search' })
157	  }
158	})
159	
160	router.delete('/:id', async (req, res) => {
161	  try {
162	    const deleted = await deleteSearch(req.params.id)
163	
164	    if (!deleted) {
165	      res.status(404).json({ error: 'Search not found' })
166	      return
167	    }
168	
169	    res.status(204).send()
170	  } catch {
171	    res.status(500).json({ error: 'Failed to delete search' })
172	  }
173	})
174	
175	export default router
